// ---- Settings you can change ----------------------------------------
const LEAD_DAYS = 2;       // remind this many days before the predicted shop
const FORCE_SEND = false;  // true = always send (use for testing, then set back to false)
const APP_URL = 'https://deelan90.github.io/ddg-grocery/?view=list';
// ----------------------------------------------------------------------

// Same rules as the Double D Grocery app (see index.html: forecast() and the Shopping List).
const raw = $input.first().json;
const data = raw.data || raw;
const DAY = 86400000;
const daysBetween = (a, b) => Math.round((b - a) / DAY);
const median = a => {
  if (!a.length) return 0;
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

// "Today" in Brisbane (no daylight saving), as a date at midnight UTC so it compares with order dates.
const todayStr = new Date(Date.now() + 10 * 3600000).toISOString().slice(0, 10);
const today = new Date(todayStr);

// ---- 1. Predict the next shop -------------------------------------------
const colesOrders = (data.orders || [])
  .filter(o => !((Number(o.items) || 0) === 0 && (Number(o.amt) || 0) <= 0));
const online = colesOrders.filter(o => !String(o.ordno || '').toUpperCase().startsWith('INSTORE'));
const basis = (online.length >= 6 ? online : colesOrders)
  .slice().sort((a, b) => new Date(a.d) - new Date(b.d));
if (basis.length < 6) {
  return [{ json: { send: false, reason: 'Not enough shop history yet' } }];
}
const dates = basis.map(o => new Date(o.d));
const gaps = [];
for (let i = 1; i < dates.length; i++) {
  const g = daysBetween(dates[i - 1], dates[i]);
  if (g > 0 && g < 60) gaps.push(g);
}
const gap = median(gaps.slice(-8));
if (!(gap > 0)) return [{ json: { send: false, reason: 'Could not work out your shopping gap' } }];
let next = new Date(dates[dates.length - 1].getTime() + gap * DAY);
while (next < today) next = new Date(next.getTime() + gap * DAY);
const daysUntil = daysBetween(today, next);
const key = next.toISOString().slice(0, 10);

// ---- 2. Find items that look low ------------------------------------------
const norm = n => String(n || '').toLowerCase().replace(/\s+/g, ' ').trim();
const lastByName = {};
(data.catalog || []).forEach(p => {
  const k = norm(p.product_name);
  if (p.last_buy && (!lastByName[k] || p.last_buy > lastByName[k])) lastByName[k] = p.last_buy;
});
const groups = {};
(data.burndown || []).forEach(b => {
  if (!b.last_bought || !(b.avg_days > 0)) return;
  const k = norm(b.product_name);
  (groups[k] = groups[k] || []).push(b);
});
const isStray = n => {
  const s = String(n || '').trim();
  return s.length < 4 || /^coles$/i.test(s) || s.replace(/[^a-zA-Z]/g, '').length < 4 || !/[a-z]/.test(s);
};
const cutoff = new Date(today.getTime() - 210 * DAY);
const due = [];
Object.entries(groups).forEach(([k, rows]) => {
  const base = rows.slice().sort((a, b) => (b.seen || 0) - (a.seen || 0))[0];
  let last = rows.map(r => r.last_bought).sort().slice(-1)[0];
  if (lastByName[k] && lastByName[k] > last) last = lastByName[k];
  const lb = new Date(last);
  if (isNaN(lb) || lb < cutoff || isStray(base.product_name)) return;
  const pct = daysBetween(lb, today) / base.avg_days * 100;
  if (pct >= 85) due.push({ name: base.product_name, importance: (base.seen || 0) * (30 / base.avg_days) });
});
due.sort((a, b) => b.importance - a.importance);
const top = due.slice(0, 5).map(d => d.name);

// ---- 3. Write the message --------------------------------------------------
const DOW = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const when = daysUntil <= 0 ? 'today'
  : daysUntil === 1 ? 'tomorrow'
  : 'on ' + DOW[next.getUTCDay()] + ' ' + next.getUTCDate() + ' ' + MON[next.getUTCMonth()];
const lastOrder = dates[dates.length - 1];
const dataAgeDays = daysBetween(lastOrder, today);
const staleNote = dataAgeDays > 45
  ? ` Heads up: your latest Coles order on file is from ${lastOrder.getUTCDate()} ${MON[lastOrder.getUTCMonth()]}, so this may be out of date.`
  : '';
const message = (due.length
  ? `Your next Coles shop looks due ${when}. ${due.length} item${due.length > 1 ? 's look' : ' looks'} low: ${top.join(', ')}${due.length > top.length ? ' and ' + (due.length - top.length) + ' more' : ''}. Want to check your list?`
  : `Your next Coles shop looks due ${when}. Nothing looks low yet, but now is a good time to write up your list.`) + staleNote;

// ---- 4. Decide whether to send (once per predicted shop) ------------------
const sd = $getWorkflowStaticData('global');
const alreadySent = sd.lastKey === key;
const send = FORCE_SEND || (daysUntil >= 0 && daysUntil <= LEAD_DAYS && !alreadySent);

return [{ json: {
  send, title: 'Grocery shop coming up', message, appUrl: APP_URL,
  key, daysUntil, dueCount: due.length, top, alreadySent, dataAgeDays
} }];

const key = $('Work out reminder').first().json.key;
// Remember this shop so you only get one reminder for it.
$getWorkflowStaticData('global').lastKey = key;
return $input.all();
